\label{def: LFRC} 
Assume $\mathcal{F}$ is defined in Eq.~\eqref{eq:function_class_f}.~\footnote{Note that the function class can cover both the widely-used hypothesis space and loss space.} 

For a fixed $r$, the LFRC of $\mathcal{F}$ can be defined as
    \begin{align} \label{eq-def:LFRC-def}
        \mathcal{R} (\mathcal{F},r) = \mathbb{E} _{S \sim D^m_{[K]}} [ \hat{\mathcal{R}} (\mathcal{F},r) ],
    \end{align}
where $S \sim D^m_{[K]}$ denotes $S_1 \sim D^{m_1}_1,S_2 \sim D^{m_2}_2,...,S_K \sim D^{m_K}_K$ for simplicity, and the empirical LFRC $\hat{\mathcal{R}} (\mathcal{F},r)$ can be defined as 




\begin{align} \label{eq: empirical LFRC}
      \hat{\mathcal{R}} (\mathcal{F},r)  
     =  \frac{1}{K} \mathbb{E} _\zeta \left [ \sup _{f \in \mathcal{F},\mathrm{var}(f_k) \leq r, k \in [K]}  \sum_{k \in [K]} \frac{1}{m_k} \sum_{j \in [J_k]} \omega_{kj}  \sum_{i \in I_{kj}} \zeta_l f_k({\mathbf{x}}_i)\right ],
\end{align} 








where $\zeta_1,\zeta_2,...,\zeta_m$ is a sequence of independent Rademacher variables: $\mathbb{P} (\zeta_l = 1) = \mathbb{P} (\zeta_l = -1) = \frac{1}{2}$.

\begin{align} \label{eq-def:LFRC-def}
        \mathcal{R} (\mathcal{F},r) = \mathbb{E} _{S \sim D^m_{[K]}} [ \hat{\mathcal{R}} (\mathcal{F},r) ],
    \end{align}

\begin{align} \label{eq: empirical LFRC}
